export class WebMaintenanceComponent implements OnInit, AfterViewInit, OnDestroy {
	bannerData: any[] = [];
	hasBanner = false;
	baseUrl: any;

	@ViewChild('myVideo') videoElement?: ElementRef<HTMLVideoElement>;
	@ViewChild('videoWrapper') videoWrapper?: ElementRef<HTMLDivElement>;
	@ViewChild('videoFrame') videoFrame?: ElementRef<HTMLDivElement>;
	@ViewChild('videoHoverBtn') videoHoverBtn?: ElementRef<HTMLDivElement>;
	@ViewChild('videoHoverBtnInner') videoHoverBtnInner?: ElementRef<HTMLDivElement>;
	@ViewChild('modalVideo')
	modalVideoElement?: ElementRef<HTMLVideoElement>;

	@ViewChild('videoModal')
	videoModal?: ElementRef<HTMLDivElement>;
	websiteFaqs = [];
	websiteTestimonials: any[] = [];

	// Smooth scroll-linked video scale (continuous rAF + lerp, driven outside Angular's zone)
	private readonly videoScaleMin = 0.5;
	private readonly videoScaleMax = 1;
	private currentVideoScale = 0.7;
	private targetVideoScale = 0.7;
	private videoScaleRafId: number | null = null;

	// Tracks the real cursor position so exiting fullscreen can resync hover state
	private lastMouseClientX = 0;
	private lastMouseClientY = 0;
	private readonly trackLastMousePosition = (event: MouseEvent): void => {
		this.lastMouseClientX = event.clientX;
		this.lastMouseClientY = event.clientY;
	};

	// Cursor-following "Play video" pill shown while hovering the video
	private hoverBtnTargetX = 0;
	private hoverBtnTargetY = 0;
	private hoverBtnCurrentX = 0;
	private hoverBtnCurrentY = 0;
	private hoverBtnRafId: number | null = null;

	private readonly handleVideoMouseMove = (event: MouseEvent): void => {
		const frame = this.videoFrame?.nativeElement;
		const btn = this.videoHoverBtn?.nativeElement;
		if (!frame || !btn) return;

		// frame.getBoundingClientRect() is in screen pixels, but the button's
		// translate3d() is applied inside .video-width-wrapper's own
		// `transform: scale(--video-scale)` — so a raw screen-pixel offset only
		// moves the button by offset * scale on screen. Divide out the scale so
		// the button tracks the cursor 1:1 instead of lagging behind it.
		const rect = frame.getBoundingClientRect();
		const scale = this.currentVideoScale || 1;
		this.hoverBtnTargetX = (event.clientX - rect.left) / scale - btn.offsetWidth / 2;
		this.hoverBtnTargetY = (event.clientY - rect.top) / scale - btn.offsetHeight / 2;
	};

	private readonly handleVideoMouseEnter = (event: MouseEvent): void => {
		this.videoFrame?.nativeElement.classList.add('is-hovering');
		this.handleVideoMouseMove(event);
		this.hoverBtnCurrentX = this.hoverBtnTargetX;
		this.hoverBtnCurrentY = this.hoverBtnTargetY;
		this.startHoverBtnLoop();
	};

	private readonly handleVideoMouseLeave = (): void => {
		this.videoFrame?.nativeElement.classList.remove('is-hovering');
		if (this.hoverBtnRafId !== null) {
			cancelAnimationFrame(this.hoverBtnRafId);
			this.hoverBtnRafId = null;
		}
	};

	private readonly handleVideoClick = (): void => {
		const inner = this.videoHoverBtnInner?.nativeElement;
		if (!inner) return;

		this.videoFrame?.nativeElement.classList.remove('is-hovering');
		inner.classList.remove('is-clicking');
		void inner.offsetWidth;
		inner.classList.add('is-clicking');
	};

	private readonly handleHoverBtnAnimationEnd = (): void => {
		this.videoHoverBtnInner?.nativeElement.classList.remove('is-clicking');
	};

	private startHoverBtnLoop(): void {
		if (this.hoverBtnRafId !== null) return;

		const step = () => {
			this.hoverBtnCurrentX += (this.hoverBtnTargetX - this.hoverBtnCurrentX) * 0.25;
			this.hoverBtnCurrentY += (this.hoverBtnTargetY - this.hoverBtnCurrentY) * 0.25;
			const btn = this.videoHoverBtn?.nativeElement;
			if (btn) {
				btn.style.transform = `translate3d(${this.hoverBtnCurrentX}px, ${this.hoverBtnCurrentY}px, 0)`;
			}
			this.hoverBtnRafId = requestAnimationFrame(step);
		};

		this.hoverBtnRafId = requestAnimationFrame(step);
	}

	private startVideoScaleLoop(): void {
		if (this.videoScaleRafId !== null) return;

		const step = () => {
			const scrollTop = window.scrollY || this.document.documentElement.scrollTop;
			this.targetVideoScale = Math.max(
				this.videoScaleMin,
				Math.min(this.videoScaleMax, this.videoScaleMin + scrollTop / 1000),
			);
			this.currentVideoScale += (this.targetVideoScale - this.currentVideoScale) * 0.12;
			this.applyVideoScale(this.currentVideoScale);

			this.videoScaleRafId = requestAnimationFrame(step);
		};

		this.videoScaleRafId = requestAnimationFrame(step);
	}

	private applyVideoScale(scale: number): void {
		this.videoWrapper?.nativeElement.style.setProperty('--video-scale', scale.toFixed(4));
	}

	private setupVideoHoverButton(): void {
		const video = this.videoElement?.nativeElement;
		if (!video) return;

		video.addEventListener('mousemove', this.handleVideoMouseMove);
		video.addEventListener('mouseenter', this.handleVideoMouseEnter);
		video.addEventListener('mouseleave', this.handleVideoMouseLeave);
		video.addEventListener('click', this.handleVideoClick);
		this.videoHoverBtnInner?.nativeElement.addEventListener(
			'animationend',
			this.handleHoverBtnAnimationEnd,
		);
	}

	private resyncVideoHoverState(video: HTMLVideoElement): void {
		const rect = video.getBoundingClientRect();
		const isOverVideo =
			this.lastMouseClientX >= rect.left &&
			this.lastMouseClientX <= rect.right &&
			this.lastMouseClientY >= rect.top &&
			this.lastMouseClientY <= rect.bottom;

		const syntheticEvent = {
			clientX: this.lastMouseClientX,
			clientY: this.lastMouseClientY,
		} as MouseEvent;
		if (isOverVideo) {
			this.handleVideoMouseEnter(syntheticEvent);
		} else {
			this.handleVideoMouseLeave();
		}
	}

	constructor(
		private bannerService: BannerService,
		private route: ActivatedRoute,
		private router: Router,
		private testimonialService: TestimonialService,
		public translationService: TranslationService,
		private faqService: FaqService,
		private cdr: ChangeDetectorRef,
		@Inject(DOCUMENT) private document: Document,
		@Inject(PLATFORM_ID) private platformId: Object,
		private ngZone: NgZone,
	) {
		this.baseUrl = environment.url;
	}

	ngOnInit(): void {
		this.getBannerdata();
		// Critical content first
		this.getBannerdata();

		// Non-critical content later
		if (!isPlatformBrowser(this.platformId)) {
			this.loadSecondaryContent();
			return;
		}

		if ('requestIdleCallback' in globalThis) {
			globalThis.requestIdleCallback(() => {
				this.loadSecondaryContent();
			});
			return;
		}

		setTimeout(() => {
			this.loadSecondaryContent();
		}, 1000);
	}
	bookConsultation() {
		this.router.navigate([this.translationService.localizedPath('/contact')], {
			state: {
				service: 'website',
			},
		});
	}
	loadSecondaryContent() {
		this.getFaqsData();
		this.getTestimonialsData();

		this.addSchema();
		this.addWebPageSchema();
		this.addBreadcrumbSchema();
	}

	addWebPageSchema() {
		const existingScript = this.document.getElementById('webpage-schema-website');
		if (existingScript) return;

		const script = this.document.createElement('script');
		script.type = 'application/ld+json';
		script.id = 'webpage-schema-website';
		script.textContent = JSON.stringify({
			'@context': 'https://schema.org',
			'@type': 'WebPage',
			name: 'Web Development Services',
			description: 'Custom website design and development solutions for modern brands.',
			url: 'https://www.pixtar.ae/services/website-development',
		});

		this.document.head.appendChild(script);
	}

	ngAfterViewInit() {
		if (!isPlatformBrowser(this.platformId)) return;

		const video = this.videoElement?.nativeElement;
		if (video) {
			video.muted = true;
			video.defaultMuted = true;
			video.volume = 0;
			video.play().catch(() => {});
		}

		this.ngZone.runOutsideAngular(() => {
			this.setupVideoHoverButton();
			window.addEventListener('mousemove', this.trackLastMousePosition, { passive: true });
		});

		this.applyVideoScale(this.currentVideoScale);
		this.ngZone.runOutsideAngular(() => {
			this.startVideoScaleLoop();
		});

		this.route.fragment.subscribe((fragment) => {
			if (!fragment) return;

			let attempts = 0;
			const maxAttempts = 20;

			const checkExist = setInterval(() => {
				const el = this.document.getElementById(fragment);
				attempts++;

				if (el) {
					el.scrollIntoView({ behavior: 'smooth' });
					clearInterval(checkExist);
				} else if (attempts >= maxAttempts) {
					clearInterval(checkExist);
				}
			}, 300);
		});
	}

	ngOnDestroy(): void {
		const video = this.videoElement?.nativeElement;
		if (video) {
			video.removeEventListener('mousemove', this.handleVideoMouseMove);
			video.removeEventListener('mouseenter', this.handleVideoMouseEnter);
			video.removeEventListener('mouseleave', this.handleVideoMouseLeave);
			video.removeEventListener('click', this.handleVideoClick);
		}
		this.videoHoverBtnInner?.nativeElement.removeEventListener(
			'animationend',
			this.handleHoverBtnAnimationEnd,
		);
		if (isPlatformBrowser(this.platformId)) {
			window.removeEventListener('mousemove', this.trackLastMousePosition);
		}
		if (this.hoverBtnRafId !== null) {
			cancelAnimationFrame(this.hoverBtnRafId);
			this.hoverBtnRafId = null;
		}
		if (this.videoScaleRafId !== null) {
			cancelAnimationFrame(this.videoScaleRafId);
			this.videoScaleRafId = null;
		}
	}

	getBannerdata() {
		const obj = {
			userUrl: '/services/website-maintenance#packages',
			btnContent: 'Explore Packages',
			btnContent_ar: 'استكشف الباقات',
		};

		this.bannerService.getHomeBanner(obj).subscribe({
			next: (response: any) => {
				if (response?.code === 200 && response?.result?.length > 0) {
					this.bannerData = response.result
						.filter((item: any) => item.page === 'website-maintenance')
						.map((item: any) => ({
							...item,
							userUrl: obj.userUrl,
							btnContent: obj.btnContent,
							btnContent_ar: obj.btnContent_ar,
						}));

					this.hasBanner = this.bannerData.length > 0;
					this.cdr.markForCheck();
				}
			},
			error: (err) => {
				console.error('Banner API error:', err);
			},
		});
	}
	playVideoInModal(): void {
		if (!isPlatformBrowser(this.platformId)) return;

		const backgroundVideo = this.videoElement?.nativeElement;
		const modalVideo = this.modalVideoElement?.nativeElement;
		const modal = this.videoModal?.nativeElement;

		if (!backgroundVideo || !modalVideo || !modal) return;

		// Stop background video
		backgroundVideo.pause();

		// Open modal
		modal.classList.add('is-open');

		// Configure modal video
		modalVideo.muted = false;
		modalVideo.volume = 1;
		modalVideo.currentTime = 0;
		modalVideo.setAttribute('controls', '');

		// Play modal video
		modalVideo.play().catch((err) => {
			console.log('Modal video play error:', err);
		});
	}
	closeVideoModal(): void {
		if (!isPlatformBrowser(this.platformId)) return;

		const backgroundVideo = this.videoElement?.nativeElement;
		const modalVideo = this.modalVideoElement?.nativeElement;
		const modal = this.videoModal?.nativeElement;

		if (!backgroundVideo || !modalVideo || !modal) return;

		// Stop modal video
		modalVideo.pause();
		modalVideo.currentTime = 0;

		// Close modal
		modal.classList.remove('is-open');

		// Resume background video
		backgroundVideo.muted = true;
		backgroundVideo.volume = 0;

		backgroundVideo.play().catch((err) => {
			console.log('Background video resume error:', err);
		});
	}
	addSchema() {
		const existingScript = this.document.getElementById('service-schema-website');
		if (existingScript) return;

		const script = this.document.createElement('script');
		script.type = 'application/ld+json';
		script.id = 'service-schema-website';
		script.textContent = JSON.stringify({
			'@context': 'https://schema.org',
			'@type': 'Service',
			name: 'Web Development Services',
			description: 'Custom website design and development solutions for modern brands.',
			url: 'https://www.pixtar.ae/services/website-development',
			serviceType: 'Website Development',
		});

		this.document.head.appendChild(script);
	}
	addBreadcrumbSchema() {
		const existingScript = this.document.getElementById('breadcrumb-schema-website');
		if (existingScript) return;

		const script = this.document.createElement('script');
		script.type = 'application/ld+json';
		script.id = 'breadcrumb-schema-website';

		script.textContent = JSON.stringify({
			'@context': 'https://schema.org',
			'@type': 'BreadcrumbList',
			itemListElement: [
				{
					'@type': 'ListItem',
					position: 1,
					name: 'Home',
					item: 'https://www.pixtar.ae/',
				},
				{
					'@type': 'ListItem',
					position: 2,
					name: 'Services',
					item: 'https://www.pixtar.ae/services',
				},
				{
					'@type': 'ListItem',
					position: 3,
					name: 'Web Development',
					item: 'https://www.pixtar.ae/services/website-development',
				},
			],
		});

		this.document.head.appendChild(script);
	}
	addFaqSchema() {
		if (!this.websiteFaqs || this.websiteFaqs.length === 0) return;

		const existingScript = this.document.getElementById('faq-schema-website');
		if (existingScript) {
			existingScript.remove();
		}

		const faqSchema = {
			'@context': 'https://schema.org',
			'@type': 'FAQPage',
			mainEntity: this.websiteFaqs.map((faq: any) => ({
				'@type': 'Question',
				name: faq.question,
				acceptedAnswer: {
					'@type': 'Answer',
					text: faq.answer,
				},
			})),
		};

		const script = this.document.createElement('script');
		script.type = 'application/ld+json';
		script.id = 'faq-schema-website';
		script.textContent = JSON.stringify(faqSchema);

		this.document.head.appendChild(script);
	}
	getFaqsData() {
		const obj = {
			type: 'Website',
		};
		this.faqService.getFaqs(obj).subscribe((res: any) => {
			if (res.code == 200) {
				this.websiteFaqs = res?.result;
				this.addFaqSchema();

				this.cdr.markForCheck();
			}
		});
	}

	getTestimonialsData() {
		const obj = {
			type: 'website',
		};
		this.testimonialService.getAlltestimonial(obj).subscribe((res: any) => {
			if (res.code == 200) {
				this.websiteTestimonials = res?.result?.filter((item: any) =>
					item.categorydata?.some((cat: any) => cat.name?.toLowerCase() === 'website'),
				);
				this.cdr.markForCheck();
			}
		});
	}
}
