import { ChangeDetectionStrategy, Component, effect, Input } from '@angular/core';

import { CommonModule } from '@angular/common';
import { TranslateModule, TranslateService } from '@ngx-translate/core';

import { TranslationService } from '../../../core/services/translation.service';

@Component({
	selector: 'app-situations',
	standalone: true,
	imports: [CommonModule, TranslateModule],
	templateUrl: './situations.component.html',
	styleUrl: './situations.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SituationsComponent {
	@Input() sectionKey = 'SITUATIONS.MAINTENANCE';

	constructor(
		public translationService: TranslationService,
		public translate: TranslateService,
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}

	getItemKeys(): string[] {
		const list = this.translate.instant(`${this.sectionKey}.LIST`);

		return list && typeof list === 'object' ? Object.keys(list) : [];
	}
}
